import{_ as s,o as t,c as r,ah as n}from"./chunks/framework.Yx0DUrwu.js";const A=JSON.parse('{"title":"常见细胞类型","description":"","frontmatter":{},"headers":[],"relativePath":"biology/common-cell-types.md","filePath":"biology/common-cell-types.md","lastUpdated":1787830595000}'),e={name:"biology/common-cell-types.md"};function i(l,a,o,c,p,C){return t(),r("div",null,[...a[0]||(a[0]=[n('<h1 id="常见细胞类型" tabindex="-1">常见细胞类型 <a class="header-anchor" href="#常见细胞类型" aria-label="Permalink to &quot;常见细胞类型&quot;">​</a></h1><p>单细胞注释的核心不是背一个标志基因，而是组合证据：细胞谱系、多个标志基因、组织来源、样本状态、细胞群内一致性和已知生物学功能。下面整理常见细胞类型、主要功能和常用标志基因，作为初步注释速查表。</p><div class="doc-callout warning"><strong>标志基因不是单基因判决</strong><p>很多标志基因会跨细胞状态或组织背景表达。例如 LYZ 可见于多种髓系细胞，EPCAM 也可能受肿瘤状态影响。注释时至少结合多个阳性标志基因、阴性标志基因和细胞群层面的表达模式。</p></div><h2 id="免疫细胞" tabindex="-1">免疫细胞 <a class="header-anchor" href="#免疫细胞" aria-label="Permalink to &quot;免疫细胞&quot;">​</a></h2><div class="check-grid"><article><strong>T 细胞</strong><span>适应性免疫核心细胞，负责细胞毒性、辅助、调节和记忆反应。常见标志基因: CD3D, CD3E, CD2, TRAC, LCK。</span></article><article><strong>CD4 T 细胞</strong><span>辅助性 T 细胞，调控 B 细胞、髓系细胞和细胞毒反应。常见标志基因: CD3D, CD4, IL7R, CCR7, LTB。</span></article><article><strong>CD8 T 细胞</strong><span>细胞毒性 T 细胞，杀伤病毒感染细胞或肿瘤细胞。常见标志基因: CD3D, CD8A, CD8B, GZMK, CCL5。</span></article><article><strong>细胞毒性 T / NK 样 T 细胞</strong><span>表达细胞毒分子，参与杀伤反应。常见标志基因: NKG7, GNLY, GZMB, PRF1, CTSW。</span></article><article><strong>调节性 T 细胞（Treg）</strong><span>免疫抑制和耐受维持。常见标志基因: FOXP3, IL2RA, CTLA4, TIGIT, IKZF2。</span></article><article><strong>耗竭样 T 细胞</strong><span>慢性抗原刺激下的功能受限状态，常见于肿瘤和慢性感染。常见标志基因: PDCD1, LAG3, HAVCR2, TIGIT, TOX, CXCL13。</span></article><article><strong>自然杀伤细胞（NK）</strong><span>先天样淋巴细胞，识别应激或低 MHC 细胞并执行杀伤。常见标志基因: NKG7, GNLY, KLRD1, FCGR3A, PRF1。</span></article><article><strong>B 细胞</strong><span>抗体产生前体、抗原呈递和体液免疫。常见标志基因: MS4A1, CD79A, CD79B, BANK1, CD74。</span></article><article><strong>浆细胞</strong><span>分泌抗体的终末分化 B 细胞。常见标志基因: MZB1, XBP1, SDC1, JCHAIN, IGKC, IGHG1。</span></article><article><strong>单核细胞</strong><span>循环髓系细胞，可迁入组织并参与炎症或分化为巨噬细胞。常见标志基因: LYZ, S100A8, S100A9, FCN1, LST1。</span></article><article><strong>巨噬细胞</strong><span>组织驻留或募集的吞噬细胞，参与清除、修复、抗原呈递和炎症调控。常见标志基因: C1QA, C1QB, C1QC, APOE, CD68, MARCO。</span></article><article><strong>树突细胞</strong><span>抗原呈递和 T 细胞启动。常见标志基因: FCER1A, CLEC10A, CD1C, CST3, LILRA4, IRF8。</span></article><article><strong>中性粒细胞</strong><span>急性炎症和抗菌反应中的粒细胞。常见标志基因: S100A8, S100A9, FCGR3B, CSF3R, CXCR2。</span></article><article><strong>肥大细胞</strong><span>过敏、屏障免疫和组织炎症。常见标志基因: TPSAB1, TPSB2, CPA3, KIT, MS4A2。</span></article></div><h2 id="上皮、内皮和基质细胞" tabindex="-1">上皮、内皮和基质细胞 <a class="header-anchor" href="#上皮、内皮和基质细胞" aria-label="Permalink to &quot;上皮、内皮和基质细胞&quot;">​</a></h2><div class="check-grid"><article><strong>上皮细胞</strong><span>覆盖组织表面或腺体结构，承担屏障、分泌和吸收功能。常见标志基因: EPCAM, KRT8, KRT18, KRT19, CDH1。</span></article><article><strong>基底细胞</strong><span>上皮干/祖细胞样群体，参与组织更新。常见标志基因: KRT5, KRT14, TP63, KRT15。</span></article><article><strong>纤毛上皮细胞</strong><span>纤毛运动和黏液清除，常见于呼吸道和生殖道。常见标志基因: FOXJ1, PIFO, TPPP3, CAPS, DNAH5。</span></article><article><strong>分泌细胞 / 杯状细胞</strong><span>分泌黏液或屏障相关蛋白。常见标志基因: MUC5AC, MUC5B, TFF3, AGR2, SPDEF。</span></article><article><strong>内皮细胞</strong><span>血管内皮，参与屏障、血管生成、凝血和免疫细胞迁移。常见标志基因: PECAM1, VWF, KDR, EMCN, CDH5。</span></article><article><strong>淋巴管内皮细胞</strong><span>淋巴管内皮，参与组织液回流和免疫细胞运输。常见标志基因: PROX1, LYVE1, PDPN, FLT4, CCL21。</span></article><article><strong>成纤维细胞</strong><span>产生细胞外基质、参与修复、纤维化和微环境塑形。常见标志基因: COL1A1, COL1A2, DCN, LUM, COL3A1。</span></article><article><strong>肌成纤维细胞</strong><span>收缩性和细胞外基质重塑更强的成纤维细胞状态。常见标志基因: ACTA2, TAGLN, MYL9, COL1A1, POSTN。</span></article><article><strong>周细胞</strong><span>包绕微血管，调节血管稳定性和屏障功能。常见标志基因: RGS5, PDGFRB, CSPG4, MCAM, NOTCH3。</span></article><article><strong>平滑肌细胞</strong><span>血管或器官壁平滑肌收缩。常见标志基因: ACTA2, MYH11, TAGLN, CNN1, TPM2。</span></article></div><h2 id="神经系统相关细胞" tabindex="-1">神经系统相关细胞 <a class="header-anchor" href="#神经系统相关细胞" aria-label="Permalink to &quot;神经系统相关细胞&quot;">​</a></h2><div class="check-grid"><article><strong>神经元</strong><span>神经信号传递。常见标志基因: SNAP25, RBFOX3, SYT1, TUBB3, MAP2。</span></article><article><strong>兴奋性神经元</strong><span>谷氨酸能兴奋性神经元。常见标志基因: SLC17A7, SLC17A6, CAMK2A, SATB2。</span></article><article><strong>抑制性神经元</strong><span>GABA 能抑制性神经元。常见标志基因: GAD1, GAD2, SLC6A1, DLX1, DLX2。</span></article><article><strong>星形胶质细胞</strong><span>支持神经元、调节代谢和突触环境。常见标志基因: GFAP, AQP4, ALDH1L1, SLC1A3。</span></article><article><strong>少突胶质细胞</strong><span>形成中枢神经系统髓鞘。常见标志基因: MBP, MOG, PLP1, MAG, MOBP。</span></article><article><strong>小胶质细胞</strong><span>中枢神经系统驻留免疫细胞。常见标志基因: P2RY12, CX3CR1, TMEM119, AIF1, C1QA。</span></article></div><h2 id="血液和其他常见细胞" tabindex="-1">血液和其他常见细胞 <a class="header-anchor" href="#血液和其他常见细胞" aria-label="Permalink to &quot;血液和其他常见细胞&quot;">​</a></h2><div class="check-grid"><article><strong>红系细胞</strong><span>负责血红蛋白表达和氧运输。常见标志基因: HBB, HBA1, HBA2, ALAS2, GYPA。</span></article><article><strong>巨核细胞 / 血小板</strong><span>血小板生成和凝血相关。常见标志基因: PPBP, PF4, GP9, ITGA2B, NRGN。</span></article><article><strong>造血干/祖细胞</strong><span>具备多谱系分化潜能。常见标志基因: CD34, SPINK2, PROM1, AVP, GATA2。</span></article><article><strong>脂肪细胞</strong><span>脂质储存和内分泌调节。常见标志基因: ADIPOQ, FABP4, PLIN1, LPL, LEP。</span></article><article><strong>肝细胞</strong><span>肝脏代谢、解毒和血浆蛋白合成。常见标志基因: ALB, APOA1, TTR, CYP3A4, FGB。</span></article><article><strong>增殖中细胞</strong><span>细胞周期活跃状态，不一定是独立细胞类型。常见标志基因: MKI67, TOP2A, STMN1, PCNA, CENPF。</span></article></div><h2 id="注释时的检查顺序" tabindex="-1">注释时的检查顺序 <a class="header-anchor" href="#注释时的检查顺序" aria-label="Permalink to &quot;注释时的检查顺序&quot;">​</a></h2><div class="flow-strip"><span>先看大谱系标志基因</span><span>再看亚群标志基因</span><span>检查阴性标志基因</span><span>查看细胞群内一致性</span><span>结合样本来源</span><span>排查双细胞</span><span>回看 QC 指标</span><span>保留不确定标签</span></div><h2 id="常见误区" tabindex="-1">常见误区 <a class="header-anchor" href="#常见误区" aria-label="Permalink to &quot;常见误区&quot;">​</a></h2><ol><li>只用一个标志基因命名细胞。</li><li>把增殖、应激、干扰素响应这类状态误当成细胞类型。</li><li>忽略组织特异性，例如成纤维细胞、巨噬细胞和内皮细胞在不同组织中的标志基因差异明显。</li><li>忽略肿瘤细胞的异常表达，尤其是上皮标志基因、MHC、细胞周期和 CNV 相关信号。</li><li>没有检查双细胞，导致 T 细胞 + 髓系细胞或上皮细胞 + 免疫细胞的混合细胞群被误注释。</li></ol>',15)])])}const P=s(e,[["render",i]]);export{A as __pageData,P as default};
